```java
import java.util.ArrayList;
import java.util.List;

class BowlingGame {

    private static final int PINS_PER_FRAME = 10;
    private static final int FRAMES = 10;

    private final List<Integer> rolls = new ArrayList<>();
    private int frame = 0;          // 0-based frame index, 0..9
    private int rollsInFrame = 0;   // rolls made in the current frame
    private int pinsInFrame = 0;    // pins knocked down in the current frame (frames 1-9)

    void roll(int pins) {
        if (pins < 0) {
            throw new IllegalStateException("Negative roll is invalid");
        }
        if (pins > PINS_PER_FRAME) {
            throw new IllegalStateException("Pin count exceeds pins on the lane");
        }

        if (frame == FRAMES - 1) {
            rollTenthFrame(pins);
        } else {
            if (rollsInFrame >= 2) {
                throw new IllegalStateException("Cannot roll after game is over");
            }
            if (pinsInFrame + pins > PINS_PER_FRAME) {
                throw new IllegalStateException("Pin count exceeds pins on the lane");
            }
            rolls.add(pins);
            rollsInFrame++;
            pinsInFrame += pins;
            if (pins == PINS_PER_FRAME || rollsInFrame == 2) {
                frame++;
                rollsInFrame = 0;
                pinsInFrame = 0;
            }
        }
    }

    private void rollTenthFrame(int pins) {
        if (rollsInFrame >= 3) {
            throw new IllegalStateException("Cannot roll after game is over");
        }
        if (rollsInFrame == 2) {
            // Second bonus roll: only allowed if the first bonus roll was a strike
            if (rolls.get(rolls.size() - 2) != PINS_PER_FRAME && pinsInFrame + pins > PINS_PER_FRAME) {
                throw new IllegalStateException("Pin count exceeds pins on the lane");
            }
        }
        rolls.add(pins);
        rollsInFrame++;
        pinsInFrame += pins;
    }

    int score() {
        if (!isGameComplete()) {
            throw new IllegalStateException("Score cannot be taken until the end of the game");
        }
        int total = 0;
        int rollIndex = 0;
        for (int i = 0; i < FRAMES; i++) {
            if (rolls.get(rollIndex) == PINS_PER_FRAME) {
                total += PINS_PER_FRAME + rolls.get(rollIndex + 1) + rolls.get(rollIndex + 2);
                rollIndex += 1;
            } else if (rolls.get(rollIndex) + rolls.get(rollIndex + 1) == PINS_PER_FRAME) {
                total += PINS_PER_FRAME + rolls.get(rollIndex + 2);
                rollIndex += 2;
            } else {
                total += rolls.get(rollIndex) + rolls.get(rollIndex + 1);
                rollIndex += 2;
            }
        }
        return total;
    }

    private boolean isGameComplete() {
        if (frame < FRAMES - 1) {
            return false;
        }
        // In the 10th frame
        if (rollsInFrame < 2) {
            return false;
        }
        // Check whether the 10th frame earned bonus rolls
        int tenthStart = rolls.size() - rollsInFrame;
        int first = rolls.get(tenthStart);
        int second = rolls.get(tenthStart + 1);
        if (first == PINS_PER_FRAME) {
            return rollsInFrame == 3;
        }
        if (first + second == PINS_PER_FRAME) {
            return rollsInFrame == 3;
        }
        return true;
    }
}
```

